// Flagship demonstrations for the Creative Director. Three fictional Ghanaian businesses, each with
// synthetic evidence, an approved Brand Kit and three concepts produced by the real deterministic
// engine. Nothing here is a real company, a downloaded photograph or a licensed font file. The
// documents under docs/creative-demos/ are generated by `npm run demo:creative`.

import type { Business } from './types';
import type { StudioObservation, StudioProject } from './studio';
import type { BrandKitContent, StudioAsset } from './studio-assets';
import {
  BRIEF_SECTION_KEYS,
  BRIEF_SECTION_LABELS,
  BRIEF_BASIS_META,
  buildCreativeBrief,
  generateCreativeDirection,
  type CreativeBriefContent,
  type CreativeDirectionContent,
  type CreativeConcept,
} from './creative-direction';
import { fontById } from './font-catalogue';

const ORG = '00000000-0000-4000-8000-0000000000ff';

export interface CreativeDemo {
  slug: string;
  business: { name: string; category: string; city: string; websiteUrl: string };
  projectId: string;
  briefVersionId: string;
  kitVersionId: string;
  kit: BrandKitContent;
  observations: {
    id: string;
    key: string;
    classification: StudioObservation['classification'];
    category: StudioObservation['category'];
    label: string;
    detail: string;
  }[];
  assets: { id: string; fileName: string; kind: StudioAsset['kind']; licence: string }[];
}

const id = (prefix: string, number: number) => `${prefix}00000000-0000-4000-8000-${String(number).padStart(12, '0')}`;

