export interface DemoResult {
  demo: CreativeDemo;
  brief: CreativeBriefContent;
  direction: CreativeDirectionContent;
  assets: StudioAsset[];
}

function demoAssets(demo: CreativeDemo): StudioAsset[] {
  return demo.assets.map((asset, index) => ({
    id: asset.id,
    organizationId: ORG,
    projectId: demo.projectId,
    fileName: asset.fileName,
    kind: asset.kind,
    status: 'approved',
    mimeType: 'image/png',
    bytes: 240_000 + index * 10_000,
    width: 1600,
    height: 2000,
    checksumSha256: String(index + 1).repeat(64).slice(0, 64),
    storagePath: `${ORG}/${demo.projectId}/${asset.id}/${asset.fileName}`,
    origin: 'client_supplied',
    ownerName: demo.business.name,
    supplier: 'Synthetic demonstration data',
    sourceUrl: null,
    licenceName: asset.licence,
    licenceReference: 'Synthetic demo licence',
    licenceExpiresOn: null,
    attributionRequired: false,
    attributionText: null,
    permissionEvidence: 'Synthetic demonstration evidence. This is not a real client file.',
    inspectPermission: 'granted',
    storePermission: 'granted',
    prototypePermission: 'granted',
    exportPermission: 'granted',
    publishPermission: 'denied',
    note: 'Synthetic demonstration asset; no bytes exist.',
    reviewNote: null,
    approvedBy: 'demo-director',
    approvedAt: '2026-10-25T09:00:00.000Z',
    rejectedBy: null,
    rejectedAt: null,
    rejectedReason: null,
    revokedBy: null,
    revokedAt: null,
    revokedReason: null,
    supersedesId: null,
    createdBy: 'demo-director',
    createdAt: '2026-10-25T09:00:00.000Z',
    updatedAt: '2026-10-25T09:00:00.000Z',
  }));
}

function demoBusiness(demo: CreativeDemo): Business {
  return {
    id: demo.projectId.replace(/^a/, 'f'),
    name: demo.business.name,
    category: demo.business.category,
    city: demo.business.city,
    officialWebsite: demo.business.websiteUrl,
  } as Business;
}

function demoProject(demo: CreativeDemo): StudioProject {
  return {
    id: demo.projectId,
    organizationId: ORG,
    businessId: demoBusiness(demo).id,
    name: `${demo.business.name} — website concept`,
    status: 'intelligence_ready',
    websiteUrl: demo.business.websiteUrl,
    brief: '',
    intelligenceStatus: 'ready',
    intelligenceAt: '2026-10-25T09:00:00.000Z',
    intelligenceNote: 'Synthetic demonstration reading.',
    createdBy: 'demo-director',
    createdAt: '2026-10-25T09:00:00.000Z',
    updatedAt: '2026-10-25T09:00:00.000Z',
  };
}

function demoObservations(demo: CreativeDemo): StudioObservation[] {
  return demo.observations.map((observation) => ({
    ...observation,
    organizationId: ORG,
    projectId: demo.projectId,
    runNumber: 1,
    confidence: 92,
    reusePermission: 'permitted',
    sourceKind: 'website_page',
    sourceUrl: demo.business.websiteUrl,
    assetUrl: null,
    assetKind: null,
    observedAt: '2026-10-25T09:00:00.000Z',
    createdBy: 'demo-director',
    createdAt: '2026-10-25T09:00:00.000Z',
  }));
}

/** Runs the real engine for one demonstration. No network, no model, no stored file. */
export function runCreativeDemo(demo: CreativeDemo): DemoResult {
  const assets = demoAssets(demo);
  const project = demoProject(demo);
  const business = demoBusiness(demo);
  const observations = demoObservations(demo);
  const brief = buildCreativeBrief({
    project,
    business,
    observations,
    reviews: [],
    kit: { versionId: demo.kitVersionId, version: 1, approvedAt: '2026-10-25T09:00:00.000Z', content: demo.kit },
    assets,
  });
  const direction = generateCreativeDirection({
    project,
    business,
    brief,
    briefVersionId: demo.briefVersionId,
    briefVersion: 1,
    kit: { versionId: demo.kitVersionId, version: 1, content: demo.kit },
    assets,
  });
  return { demo, brief, direction, assets };
}

export function creativeDemoPack(): DemoResult[] {
  return CREATIVE_DEMOS.map(runCreativeDemo);
}

const basisLabel = (basis: string) => BRIEF_BASIS_META[basis as keyof typeof BRIEF_BASIS_META]?.label ?? basis;
const bullets = (values: string[]) => values.map((value) => `- ${value}`).join('\n');
const table = (headers: string[], rows: string[][]) =>
  [`| ${headers.join(' | ')} |`, `| ${headers.map(() => '---').join(' | ')} |`, ...rows.map((row) => `| ${row.join(' | ')} |`)].join('\n');

function briefMarkdown(brief: CreativeBriefContent): string {
  const sections = BRIEF_SECTION_KEYS.map((key) => {
    const section = brief.sections[key];
    const assertions = section.assertions.map((assertion) => {
      const evidence = [
        assertion.evidence.observationIds.length ? `${assertion.evidence.observationIds.length} observation(s)` : null,
        assertion.evidence.assetIds.length ? `${assertion.evidence.assetIds.length} approved file(s)` : null,
        assertion.evidence.brandKitVersion ? `Brand Kit v${assertion.evidence.brandKitVersion}` : null,
        assertion.evidence.record.length ? assertion.evidence.record.join(', ') : null,
      ].filter(Boolean);
      return `- **${basisLabel(assertion.basis)}** — ${assertion.text}${evidence.length ? ` _(${evidence.join('; ')})_` : ''}`;
    });
    return [`### ${BRIEF_SECTION_LABELS[key]}`, '', section.summary, '', ...assertions].join('\n');
  }).join('\n\n');

  const palette = table(
    ['Colour', 'Role', 'Hex'],
    brief.colour.palette.map((entry) => [entry.name, entry.role.replace(/_/g, ' '), entry.hex]),
  );
  const contrast = table(
    ['Use', 'Ratio', 'AA'],
    brief.colour.contrast.map((check) => [check.usage, `${check.ratio}:1`, check.passesAA ? 'Pass' : 'Fail']),
  );
  const missing = brief.missingInformation.map((item) => `- ${item.blocking ? '**Blocking:** ' : ''}${item.question} — ${item.why}`).join('\n');
  const confirmations = brief.confirmations.map((item) => `- ${item.required ? '**Required:** ' : ''}${item.item} — ${item.why}`).join('\n');

  return [
    `## Creative Direction Brief (version 1)`,
    '',
    `**${brief.provenance.verified} verified · ${brief.provenance.brandKit} from the approved kit · ${brief.provenance.assets} approved files · ${brief.provenance.suggestions} creative suggestions · ${brief.provenance.standards} Studio standards · ${brief.provenance.confirmations} client confirmations.**`,
    '',
    `**Typography:** ${brief.typography.rationale}`,
    '',
    `Licences: ${brief.typography.licences.join('; ')}. Languages: ${brief.languages.join(', ')}.`,
    '',
    palette,
    '',
    contrast,
    '',
    sections,
    '',
    '### Missing information',
    '',
    missing,
    '',
    '### Client confirmations',
    '',
    confirmations,
    '',
  ].join('\n');
}

function conceptMarkdown(concept: CreativeConcept, index: number): string {
  const display = fontById(concept.typography.displayFontId);
  const body = fontById(concept.typography.bodyFontId);
  const palette = table(
    ['Colour', 'Role', 'Hex'],
    concept.colour.palette.map((entry) => [entry.name, entry.role.replace(/_/g, ' '), entry.hex]),
  );
  const contrast = table(
    ['Use', 'Ratio', 'AA'],
    concept.colour.contrast.map((check) => [check.usage, `${check.ratio}:1`, check.passesAA ? 'Pass' : 'Fail']),
  );
  const scale = table(
    ['Step', 'Min', 'Max', 'Line height', 'Tracking', 'Use'],
    concept.tokens.type.steps.map((step) => [step.name, `${step.minRem}rem`, `${step.maxRem}rem`, String(step.lineHeight), step.tracking, step.use]),
  );
  const quality = table(
    ['Dimension', 'Score', 'Advisory note'],
    concept.quality.dimensions.map((dimension) => [dimension.label, `${dimension.score}/100`, dimension.note]),
  );
  const refs = concept.imagery.references.map((reference) => `- ${reference.title}${reference.url ? ` — ${reference.url}` : ''} (${reference.licence}). ${reference.note}`).join('\n');
  const chapters = concept.story.chapters.map((chapter) => `- **${chapter.name}** — ${chapter.intent}`).join('\n');

  return [
    `## ${index + 1}. ${concept.name}`,
    '',
    `> ${concept.idea}`,
    '',
    concept.narrative,
    '',
    `**Composition:** ${concept.composition.label}. ${concept.composition.grid}`,
    '',
    `**Typography:** ${display?.family ?? concept.typography.displayFamily} / ${body?.family ?? concept.typography.bodyFamily}. ${concept.typography.rationale}`,
    '',
    `Licences: ${concept.typography.licence.display}; ${concept.typography.licence.body}. Languages: ${concept.typography.languages.join(', ')}.`,
    '',
    scale,
    '',
    `**Colour logic:** ${concept.colour.strategy}`,
    '',
    palette,
    '',
    contrast,
    '',
    `**Imagery:** ${concept.imagery.direction}`,
    '',
    `Treatment: ${concept.imagery.treatment}`,
    '',
    concept.imagery.missing.length ? `**Commission:** ${concept.imagery.missing.join(' ')}` : '**Assets:** approved files in the vault cover the direction.',
    '',
    `**Motion:** ${concept.motion.label}. ${concept.motion.idea} ${concept.motion.spec.durationMs}ms, ${concept.motion.spec.easing}, ${concept.motion.spec.properties.join('/')}.`,
    '',
    `Reduced motion: ${concept.motion.reducedMotion}`,
    '',
    `**Conversion:** ${concept.conversion.primaryCta}. ${concept.conversion.path.join(' → ')}.`,
    '',
    `**Story:** ${concept.story.premise}`,
    '',
    chapters,
    '',
    `**Rationale:** ${concept.rationale.audience} ${concept.rationale.business}`,
    '',
    concept.rationale.evidence.observationLabels.length
      ? `Evidence: ${concept.rationale.evidence.observationLabels.map((label) => `“${label}”`).join('; ')} (${concept.rationale.evidence.observationIds.length} observation(s)).`
      : 'No verified observation is cited.',
    '',
    '**Trade-offs accepted:**',
    '',
    bullets(concept.tradeoffs),
    '',
    '**Risks to watch:**',
    '',
    bullets(concept.risks),
    '',
    '**References:**',
    '',
    refs,
    '',
    `**Advisory review — ${concept.quality.overall}/100.** ${concept.quality.advisory}`,
    '',
    quality,
    '',
  ].join('\n');
}

/** The full demonstration document, ready to commit under docs/creative-demos/. */
export function demoMarkdown(result: DemoResult): string {
  const { demo, brief, direction } = result;
  const comparison = table(
    ['Dimension', ...direction.concepts.map((concept) => concept.name)],
    direction.comparison.map((row) => [row.dimension, ...row.values.map((value) => value.value)]),
  );
  const recommendation = direction.concepts.find((concept) => concept.key === direction.recommendation.conceptKey);
  return [
    `# ${demo.business.name} — Creative Direction`,
    '',
    `**${demo.business.category} · ${demo.business.city} · ${demo.business.websiteUrl}**`,
    '',
    '> Synthetic demonstration. This business, its evidence, its files and its licence records are fictional and exist only to show the Creative Director at work. No photograph, font file or page was fetched. The real engine generated every section below from the synthetic evidence and the approved (synthetic) Brand Kit.',
    '',
    `Brand Kit version 1 · brief version 1 · generated by the deterministic Studio engine · seed *${direction.seed}*`,
    '',
    briefMarkdown(brief),
    '',
    '---',
    '',
    '## The three concepts',
    '',
    comparison,
    '',
    `**Advisory recommendation:** ${recommendation?.name ?? 'none'}. ${direction.recommendation.why}`,
    '',
    ...direction.concepts.map((concept, index) => conceptMarkdown(concept, index)),
    '',
    '---',
    '',
    '## Limitations',
    '',
    bullets(direction.limitations),
    '',
    `**${direction.recommendation.advisory}**`,
    '',
  ].join('\n');
}

export interface CreativeDemoDocument {
  slug: string;
  markdown: string;
  brief: CreativeBriefContent;
  direction: CreativeDirectionContent;
}

/** Deterministic package written by `npm run demo:creative`. */
export function generateCreativeDemoDocuments(): CreativeDemoDocument[] {
  return creativeDemoPack().map((result) => ({
    slug: result.demo.slug,
    markdown: demoMarkdown(result),
    brief: result.brief,
    direction: result.direction,
  }));
}





